// Keeps the phone's screen on during a game, so a phone lying on the table between turns doesn't
// lock and drop its player.
//
// The Screen Wake Lock API does exactly this, but browsers only offer it on https pages (and
// localhost), and phones reach Couchcade over plain http on the home network. So where it's
// missing, a tiny silent looping video plays out of sight instead: phones keep the screen on
// while a video plays. Both need a tap to start, so start() is called from tap handlers.
// The video is embedded here (2 s of 16x16 black, about 2 KB) so it needs no file, no server
// change and works in the packaged apps too.

const MP4 = 'data:video/mp4;base64,';
const WEBM = 'data:video/webm;base64,';

let wanted = false;
let lock = null;
let video = null;

/** Keep the screen on from now until stop(). Safe to call often (every tap). */
export function start() {
  wanted = true;
  if ('wakeLock' in navigator && window.isSecureContext) {
    if (!lock) {
      navigator.wakeLock.request('screen').then((l) => {
        lock = l;
        l.addEventListener('release', () => (lock = null));
        if (!wanted) stop();
      }).catch(() => playVideo()); // refused (battery saver, iframe): try the video
    }
    return;
  }
  playVideo();
}

/** Let the screen sleep normally again (back in the lobby). */
export function stop() {
  wanted = false;
  lock?.release().catch(() => {});
  lock = null;
  video?.pause();
}

function playVideo() {
  if (!video) {
    video = document.createElement('video');
    video.setAttribute('playsinline', '');
    video.setAttribute('muted', '');
    video.muted = true;
    video.loop = true;
    video.setAttribute('aria-hidden', 'true');
    video.style.cssText = 'position:fixed;left:0;top:0;width:1px;height:1px;opacity:0.01;pointer-events:none;';
    for (const [type, src] of [['video/webm', WEBM], ['video/mp4', MP4]]) {
      const s = document.createElement('source');
      s.type = type;
      s.src = src;
      video.append(s);
    }
    document.body.append(video);
  }
  if (video.paused) video.play().catch(() => {}); // not allowed yet: the next tap tries again
}

// A lock is dropped whenever the page is hidden (screen off, app switch). Take it again on return.
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'visible' && wanted) start();
});
